per_item.gold_sql:
SELECT d.dept_nm, COUNT(e.emp_id) AS n
                       FROM depts d LEFT JOIN employees e ON d.dept_cd = e.dept_cd
                       GROUP BY d.dept_cd;

per_item.pred_sql:
SELECT COUNT(*) AS employee_count
FROM employees
WHERE sal IS NOT NULL;

per_item.gold_sql:
SELECT e.emp_nm FROM employees e
                       WHERE e.sal > (SELECT AVG(e2.sal) FROM employees e2
                                      WHERE e2.dept_cd = e.dept_cd);

per_item.pred_sql:
SELECT e.emp_nm AS employee_name, COALESCE(m.emp_nm, 'No Manager') AS manager_name
FROM employees e
LEFT JOIN employees m ON e.mgr_id = m.emp_id;

per_item.gold_sql:
SELECT p.proj_nm, COALESCE(SUM(a.hrs), 0) AS total_hrs
                       FROM projects p LEFT JOIN assignments a ON p.proj_id = a.proj_id
                       GROUP BY p.proj_id;

per_item.pred_sql:
SELECT d.dept_nm, r.region_nm
FROM depts d
LEFT JOIN regions r ON d.region_cd = r.region_cd;

SELECT d.dept_nm, COALESCE(b.amt, 0) AS budget_2025
FROM depts d
LEFT JOIN budgets b ON d.dept_cd = b.dept_cd AND b.fy = 2025;

per_item.gold_sql:
SELECT emp_nm, dept_cd,
                              RANK() OVER (PARTITION BY dept_cd ORDER BY sal DESC) AS rnk
                       FROM employees;

SELECT e.dept_cd, e.emp_nm FROM employees e
                       WHERE e.sal = (SELECT MAX(e2.sal) FROM employees e2
                                      WHERE e2.dept_cd = e.dept_cd);

SELECT m.emp_nm, COUNT(e.emp_id) FROM employees m
                       JOIN employees e ON e.mgr_id = m.emp_id
                       GROUP BY m.emp_id;

SELECT SUM(a.hrs) FROM assignments a
                       JOIN employees e ON a.emp_id = e.emp_id
                       WHERE e.dept_cd = 'ENG';
